// TH18 v1.00a st02bs::BossCard1/source371-539. Source t0=card124.
const TIME_LIMIT: int = 2222;
const SOURCE_LIMIT: int = 2100;

xformdef LEAF_MOTION(omega: angle) {
    offscreen_keep(200); // Source515: b0 finite offscreen protection; independent of polar motion.
    set_ang_vel(omega);
    @200 set_accel(0.012fx);
    set_ang_vel(0bam);
    set_accel(0fx);
}
sub sample_count() {
    var rank: int = global(GVAR_RANK);
    var start: int = 3;
    var delta: int = 2;
    if rank == 1 { delta = 3; }
    if rank >= 2 { start = 5; }
    // Source floatTime0 starts at source90, writes start immediately, then advances at frame tail.
    // Positive values: _S(start+delta*elapsed/2100) is exactly this integer floor.
    var elapsed: int = $frame-self_int(2)-90;
    set_self_int(3, start+delta*elapsed/2100);
}
sub configure(omega: angle) {
    sh_reset(0);
    sh_sprite(0, TH18_DROPLET, 10);
    sh_aim(0, 0);
    sh_ring(0, 0);
    sh_count(0, 1, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, 26fx); // Source dist32, ANIM a1 retreat4*1.5; rest of birth stage omitted.
    sh_offset(0, 0fx, -16fx);
    sh_xform(0, LEAF_MOTION(omega));
}
sub emit_fan(center: angle, n: int) {
    // Preserve source fixed-fan creation order for both odd and even N.
    for i in 0..n {
        var off: int = ((i+1)/2)*3641; //20deg nearest BAM.
        if n%2 == 0 { off = (2*(i/2)+1)*3641/2; }
        if i%2 != 0 { off = -off; }
        sh_angle(0, center+(off as angle), 0deg);
        sh_fire(0);
    }
}
sub sync_helper(n: int, turn: int, omega: angle, interval: int) {
    configure(omega);
    for j in 0..15 {
        if $frame >= self_int(1) { return; }
        emit_fan((-16384-j*turn) as angle, n);
        card_wait(interval); // Includes last emission's wait, and only this main task advances movement.
    }
}
async sub async_helper(n: int, turn: int, omega: angle, interval: int) {
    // n is copied at source call time; target/source async both first run on the following frame.
    configure(omega);
    for j in 0..15 {
        if $frame >= self_int(1) { return; }
        emit_fan((-16384-j*turn) as angle, n);
        wait(interval); // Includes trailing wait; never advances shared movement a second time.
    }
}
async sub pattern() {
    wait(120);
    set_self_int(2, $frame);
    set_self_int(1, $frame+SOURCE_LIMIT);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    var rank: int = global(GVAR_RANK);
    var gap: int = 30;
    var interval: int = 5;
    var turn: int = 4005; // Source C=.383972rad (~22deg).
    if rank == 0 { gap = 60; turn = 3459; } // Source C=.331613rad (~19deg).
    if rank == 2 { interval = 4; }
    if rank == 3 { interval = 3; }
    wait(90);
    loop {
        if $frame >= self_int(1) { return; }
        sample_count();
        spawn async_helper(self_int(3), turn, 164bam, interval);
        card_wait(gap);
        if $frame >= self_int(1) { return; }
        sample_count();
        sync_helper(self_int(3), -turn, -164bam, interval);
        if $frame >= self_int(1) { return; }
        card_move_rand();
        sample_count();
        spawn async_helper(self_int(3), -turn, -164bam, interval);
        card_wait(gap);
        if $frame >= self_int(1) { return; }
        sample_count();
        sync_helper(self_int(3), turn, 164bam, interval);
        if $frame >= self_int(1) { return; }
        card_move_rand();
    }
}
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    spell_begin(0, 8, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 v1.00a BossCard1 only. int0=next-step, int1=source end, int2=source start, int3=sampled ray count; fx0/1=logical unit vector.
// All source wait(n) inside this attack must use card_wait(n), in the same owner task.
// No new task: emit uses the current position, phase5 then performs the next source movement tick.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.7fx*((60-k) as fx)/60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -60fx { nx = -60fx; }
    if nx > 60fx { nx = 60fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 405b90 = signed unit random * pi. Values below are unwrapped BAM ints.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -30fx {
        a = r/3;
    } else if $self_x > 30fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon0.05rad. Nearest BAM boundaries (normal angle quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}
